'use strict';

const toRegexRange = require('to-regex-range');

/**
 * Parse a range string like "1-100" into [min, max].
 * Accepts surrounding whitespace and negative numbers (e.g. "-10--1").
 */
function parseRange(input) {
  const match = /^\s*(-?\d+)\s*-\s*(-?\d+)\s*$/.exec(String(input));
  if (!match) {
    throw new Error(`Invalid range "${input}". Expected format: <min>-<max>, e.g. 1-100`);
  }
  let min = Number(match[1]);
  let max = Number(match[2]);
  if (!Number.isSafeInteger(min) || !Number.isSafeInteger(max)) {
    throw new Error(`Range bounds must be safe integers: "${input}"`);
  }
  if (min > max) [min, max] = [max, min];
  return [min, max];
}

/**
 * Convert a range string into a regex source string (no anchors).
 */
function rangeToPattern(input) {
  const [min, max] = parseRange(input);
  return toRegexRange(min, max);
}

/**
 * Convert a range string into an anchored RegExp that matches a whole number in range.
 */
function rangeToRegex(input) {
  return new RegExp(`^(?:${rangeToPattern(input)})$`);
}

module.exports = { parseRange, rangeToPattern, rangeToRegex };
EOF
cat > src/cli.js <<'EOF'
#!/usr/bin/env node
'use strict';

const { rangeToPattern } = require('./range-to-regex');

const args = process.argv.slice(2);
const anchored = !args.includes('--no-anchors');
const range = args.find((a) => !a.startsWith('--'));

if (!range || args.includes('--help')) {
  console.error('Usage: range-to-regex <min>-<max> [--no-anchors]');
  console.error('Example: range-to-regex 1-100');
  process.exit(range ? 0 : 1);
}

try {
  const pattern = rangeToPattern(range);
  console.log(anchored ? `^(?:${pattern})$` : pattern);
} catch (err) {
  console.error(err.message);
  process.exit(1);
}
EOF
chmod +x src/cli.js
cat > test/range-to-regex.test.js <<'EOF'
'use strict';

const test = require('node:test');
const assert = require('node:assert');
const { parseRange, rangeToRegex } = require('../src/range-to-regex');

function assertExact(range, min, max) {
  const re = rangeToRegex(range);
  for (let n = min - 50; n <= max + 50; n++) {
    assert.strictEqual(re.test(String(n)), n >= min && n <= max, `${range}: ${n}`);
  }
}

test('1-100 matches exactly 1..100', () => assertExact('1-100', 1, 100));
test('0-9', () => assertExact('0-9', 0, 9));
test('17-4321', () => assertExact('17-4321', 17, 4321));
test('negative range', () => assertExact('-25--3', -25, -3));
test('range crossing zero', () => assertExact('-10-10', -10, 10));
test('single value', () => assertExact('42-42', 42, 42));
test('reversed bounds are swapped', () => assert.deepStrictEqual(parseRange('100-1'), [1, 100]));
test('rejects partial matches', () => {
  const re = rangeToRegex('1-100');
  for (const s of ['1000', '0', 'a5', '5a', '', '1.5']) assert.strictEqual(re.test(s), false, s);
});
test('invalid input throws', () => {
  for (const s of ['abc', '1-', '-', '1..100', '1-2-3']) assert.throws(() => parseRange(s), s);
});
EOF
